# -*- coding: utf-8 -*-
# أمثلة تطبيقية رقمية وأخطاء شائعة تُضاف بعد المحتوى الأساسي للمعايير (تُدمج ولا تستبدل)
DEEPA={
"IAS 2":[("مثال تطبيقي رقمي",["اشترت منشأة 1,000 وحدة بسعر 20 ريالًا وتكاليف نقل 1,000 ريال. التكلفة الكلية 21,000 أي 21 ريالًا للوحدة. في نهاية الفترة بقيت 200 وحدة ويُتوقع بيعها بسعر 18 ريالًا ومصاريف بيع 2 ريال للوحدة، فصافي القيمة القابلة للتحقق 16 ريالًا للوحدة.","التخفيض المطلوب: (21 − 16) × 200 = 1,000 ريال.","قيد: مدين: مصروف انخفاض قيمة المخزون 1,000 / دائن: مخصص مخزون 1,000."]),("أخطاء شائعة",["• رسملة تكاليف التخزين غير اللازمة للإنتاج ضمن تكلفة المخزون.","• نسيان إعادة تقييم صافي القيمة القابلة للتحقق كل فترة تقرير.","• استخدام طريقة LIFO وهي غير مسموحة بالمعيار."])],
"IAS 16":[("مثال تطبيقي رقمي",["اشترت منشأة آلة بـ 200,000 ريال ودفعت 10,000 للنقل و15,000 للتركيب، وجهّزتها للتشغيل. التكلفة المرسملة 225,000. العمر 10 سنوات وقيمة متبقية 25,000، فالإهلاك السنوي بالقسط الثابت (225,000 − 25,000) ÷ 10 = 20,000.","قيد: مدين: آلات 225,000 / دائن: بنك 225,000. ثم سنويًا: مدين: مصروف إهلاك 20,000 / دائن: مجمع الإهلاك 20,000."]),("أخطاء شائعة",["• تحميل التركيب والنقل كمصروف بدل رسملتهما.","• إهلاك الأراضي.","• عدم مراجعة العمر الإنتاجي والقيمة المتبقية سنويًا.","• عدم إهلاك المكونات المهمة المختلفة الأعمار كلٌّ على حدة."])],
"IFRS 15":[("مثال تطبيقي رقمي",["باعت منشأة جهازًا مع سنة صيانة بسعر إجمالي 12,000 ريال. السعر المستقل للجهاز 10,000 وللصيانة 2,000. يُوزَّع الثمن بنسبة الأسعار المستقلة: الجهاز 10,000 والصيانة 2,000.","عند التسليم يُعترف بإيراد 10,000، وتُؤجَّل الصيانة وتُعترف شهريًا 2,000 ÷ 12 = 166.67.","قيد عند البيع نقدًا: مدين: بنك 12,000 / دائن: إيراد مبيعات 10,000 / دائن: إيراد مؤجل 2,000."]),("خطوات النموذج الخمس",["• تحديد العقد مع العميل.","• تحديد التزامات الأداء المنفصلة.","• تحديد سعر المعاملة.","• توزيع السعر على الالتزامات.","• الاعتراف بالإيراد عند الوفاء بكل التزام."])],
"IFRS 16":[("مثال تطبيقي رقمي",["إيجار 5 سنوات بدفعة سنوية 100,000 ريال تُدفع آخر السنة، ومعدل الاقتراض الإضافي 8%. القيمة الحالية للدفعات = 100,000 × [1 − 1.08^-5] ÷ 0.08 ≈ 399,271 ريالًا.","قيد البداية: مدين: أصل حق استخدام 399,271 / دائن: التزام إيجار 399,271.","السنة الأولى: فائدة 399,271 × 8% = 31,942. الإهلاك 399,271 ÷ 5 = 79,854. بعد الدفعة: التزام الإيجار = 399,271 + 31,942 − 100,000 = 331,213."]),("استثناءات تبسيطية",["• عقود 12 شهرًا فأقل.","• الأصول منخفضة القيمة (أجهزة صغيرة)، وتُحمَّل دفعاتها كمصروف بالقسط الثابت."])],
"IAS 12":[("مثال تطبيقي رقمي",["اشترت منشأة أصلًا بـ 100,000 ريال. الإهلاك المحاسبي 20% سنويًا والإهلاك الضريبي 40%. في السنة الأولى: القيمة الدفترية 80,000 والأساس الضريبي 60,000، والفرق المؤقت الخاضع للضريبة 20,000. بمعدل ضريبة 20% يكون التزام الضريبة المؤجلة 4,000.","قيد: مدين: مصروف ضريبة مؤجلة 4,000 / دائن: التزام ضريبة مؤجلة 4,000."]),("ملاحظة",["• ضريبة الدخل المؤجلة تخص الشركات الخاضعة لضريبة الدخل؛ أما الزكاة فتعالج وفق معالجة منشأتك ومتطلبات الهيئة وتعليمات الجهات المهنية، فاستشر مختصًا."])],
"IFRS 9":[("مثال تطبيقي رقمي",["أقرضت منشأة 100,000 ريال بفائدة اسمية 5% سنويًا، وسُجّلت بالتكلفة المطفأة. إذا كان مخصص الخسارة المتوقعة 12 شهرًا 2,000 ريال في البداية: مدين: مصروف خسائر ائتمانية 2,000 / دائن: مخصص خسائر 2,000.","إذا ارتفعت مخاطر الائتمان ارتفاعًا جوهريًا (المرحلة الثانية) يصبح المخصص على مدى عمر الأداة، وليس 12 شهرًا فقط."]),("المراحل الثلاث",["• المرحلة 1: لا زيادة جوهرية في المخاطر، خسارة 12 شهرًا.","• المرحلة 2: زيادة جوهرية، خسارة عمر الأداة.","• المرحلة 3: انخفاض ائتماني فعلي، خسارة عمر الأداة وفائدة على الصافي."])],
"IAS 36":[("مثال تطبيقي رقمي",["أصل قيمته الدفترية 500,000 ريال. القيمة العادلة ناقصًا تكلفة البيع 380,000 وقيمة الاستخدام 420,000، فالمبلغ القابل للاسترداد هو الأعلى 420,000. خسارة الانخفاض = 500,000 − 420,000 = 80,000.","قيد: مدين: خسارة انخفاض قيمة الأصل 80,000 / دائن: مجمع انخفاض القيمة 80,000."]),("متى تختبر؟",["• سنويًا للشهرة والأصول غير المحددة العمر.","• عند وجود مؤشر انخفاض لأي أصل: تغير السوق، تقادم، أداء أسوأ من المتوقع."])],
"IAS 37":[("مثال تطبيقي رقمي",["رُفعت على منشأة قضية، ويرى المستشار القانوني أن الخسارة محتملة (أكثر من 50%) والمبلغ المتوقع 150,000 ريال. تُسجَّل مخصصًا: مدين: مصروف مطالبات 150,000 / دائن: مخصص قضايا 150,000.","لو كانت الخسارة ممكنة وليست محتملة فلا يُسجَّل مخصص، بل يُفصح عن التزام محتمل في الإيضاحات."]),("الفرق بين البنود",["• مخصص: التزام محتمل الوقوع وقابل للقياس يُسجَّل.","• التزام محتمل: يُفصح عنه فقط.","• أصل محتمل: لا يُسجَّل، ويُفصح إن كان تدفق المنافع شبه مؤكد."])],
"IAS 19":[("مثال تطبيقي رقمي",["موظف أجره 6,000 ريال وخدمته 4 سنوات. مكافأة نهاية الخدمة التقديرية = 0.5 × 6,000 × 4 = 12,000. الاستحقاق الشهري التقريبي 6,000 × 0.5 ÷ 12 = 250.","قيد: مدين: مصروف مكافأة نهاية الخدمة 250 / دائن: التزام مكافأة نهاية الخدمة 250."])],
"IAS 21":[("مثال تطبيقي رقمي",["اشترت منشأة بضاعة بـ 10,000 دولار حين كان الصرف 3.75 ريال، فسُجّلت بـ 37,500. وقت السداد كان الصرف 3.76 فدفعت 37,600، والفرق 100 خسارة فروق عملة محققة.","قيد السداد: مدين: ذمم دائنة 37,500 + خسارة فروق عملة 100 / دائن: بنك 37,600."])],
"IAS 7":[("نصيحة تطبيقية",["• ابدأ من الميزانية وقائمة الدخل: صافي التغير في كل حساب يُترجم إلى حركة نقد أو تعديل غير نقدي.","• راجع الدليل العملي: قائمة التدفقات النقدية بالطريقة غير المباشرة بمثال محلول."])],
"IAS 1":[("قائمة تحقق للعرض",["• هل كل قائمة معنونة بالمنشأة والتاريخ والعملة؟","• هل يتوفر رقم مقارن للفترة السابقة؟","• هل صُنّف المتداول وغير المتداول بشكل صحيح؟","• هل الإيضاحات تشرح السياسات والتقديرات الهامة؟"])],
"IAS 8":[("أمثلة للتمييز",["• تغيير عمر آلة من 10 إلى 8 سنوات: تقدير، يُطبَّق مستقبلًا.","• تغيير طريقة تقييم المخزون من المتوسط إلى FIFO: تغيير سياسة، بأثر رجعي ما أمكن.","• اكتشاف عدم تسجيل فاتورة العام الماضي رغم توفر بياناتها: خطأ، يُصحَّح بأثر رجعي."])],
"IFRS 3":[("خطوات المحاسبة عن الاندماج",["• تحديد المستحوِذ وتاريخ الاستحواذ.","• قياس الأصول المقتناة والالتزامات المقبولة بالقيمة العادلة.","• حساب الشهرة = المقابل المحوَّل + الحصة غير المسيطرة − صافي الأصول القابلة للتحديد.","• اختبار الشهرة سنويًا للانخفاض وفق IAS 36 وعدم إطفائها."])],
"IFRS 17":[("للمنشآت غير العاملة في التأمين",["المعيار يخص عقود التأمين وإعادة التأمين، ولا ينطبق على أغلب المنشآت التجارية. إن كان نشاطك تجاريًا فيكفي أن تعرف أنه موجود، وتركّز على IFRS 15 وIFRS 9 وIFRS 16."])],
"IFRS S1":[("ما الذي يعنيه عمليًا؟",["• الإفصاح عن المخاطر والفرص المرتبطة بالاستدامة التي قد تؤثر على التدفقات والتمويل وقيمة المنشأة.","• ربط المعلومات بالقوائم المالية نفسها وبالفترة نفسها.","• الحوكمة والاستراتيجية وإدارة المخاطر والمقاييس والأهداف هي محاور الإفصاح."])],
"IFRS S2":[("ما الذي يعنيه عمليًا؟",["• قياس الانبعاثات (النطاقات 1 و2 و3) والمخاطر الانتقالية والمادية للمناخ.","• تحليل سيناريوهات المناخ وأثرها على الاستراتيجية.","• اعتماد منهجية موثّقة لحساب الانبعاثات وبيانات قابلة للتدقيق."])],
"IFRS for SMEs":[("متى تناسب منشأتك؟",["• المنشآت التي ليست لها مساءلة عامة وتعد قوائم لأغراض عامة.","• تبسيط في القياس والإفصاح مقارنة بالمعايير الكاملة.","• تحقق من اشتراطات الجهة المنظمة في بلدك قبل اختيار الإطار."])],
}
